def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_rate = opp_c / n

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            opp_c_streak += 1
        else:
            break

    recent_len = min(12, n)
    recent_op = op[-recent_len:]
    recent_opp_c = sum(1 for x in recent_op if x == 'C')
    recent_rate = recent_opp_c / recent_len

    recent3_len = min(3, n)
    recent3_my_d = sum(1 for x in my[-recent3_len:] if x == 'D')

    d_count = 0
    d_to_c = 0
    recent_d_count = 0
    recent_d_to_c = 0
    start_recent = max(0, n - 12)

    for i in range(n - 1):
        if my[i] == 'D':
            d_count += 1
            if op[i + 1] == 'C':
                d_to_c += 1
            if i >= start_recent:
                recent_d_count += 1
                if op[i + 1] == 'C':
                    recent_d_to_c += 1

    if opp_rate < 0.22 and recent_rate < 0.35:
        return 'D'

    last_my = my[-1]
    last_opp = op[-1]

    if last_opp == 'D':
        if opp_d_streak >= 5 or (opp_d_streak >= 3 and recent_rate < 0.25 and opp_rate < 0.60):
            return 'D'

        if last_my == 'D' or recent3_my_d > 0:
            if opp_rate > 0.55 or recent_rate > 0.45:
                if opp_d_streak >= 4 and last_my == 'C':
                    return 'D'
                return 'C'
            return 'D'

        if opp_d_streak == 1 and opp_rate > 0.85 and recent_rate > 0.70:
            return 'C'
        if opp_d_streak == 1 and recent_rate > 0.50 and opp_rate > 0.60:
            return 'C'
        return 'D'

    if recent_rate < 0.30 and opp_rate < 0.60:
        return 'D'
    if opp_rate < 0.25:
        return 'D'

    all_clean = d_count > 0 and d_to_c == d_count
    recent_clean = recent_d_count > 0 and recent_d_to_c == recent_d_count

    if ((d_count >= 5 and all_clean and recent_rate >= 0.65 and opp_rate >= 0.60) or
        (recent_d_count >= 3 and recent_clean and recent_rate >= 0.55 and opp_rate >= 0.55)):
        return 'D'

    if ((d_count >= 2 and all_clean and recent_rate >= 0.55 and opp_rate >= 0.50) or
        (recent_d_count >= 2 and recent_clean and recent_rate >= 0.55 and opp_rate >= 0.50)):
        if last_my == 'D':
            return 'C'
        return 'D'

    if (n >= 30 and
        last_my == 'C' and
        opp_c_streak >= 20 and
        opp_rate >= 0.95 and
        recent_rate >= 0.95):
        if d_count == 0 or (d_count < 2 and all_clean):
            return 'D'

    return 'C'
